CREATE PROCEDURE plus_one(x INT64)
RETURNS result INT64
AS {
  RETURN x + 1 AS result
};

CREATE PROCEDURE greet(name STRING, prefix STRING DEFAULT "hi")
RETURNS message STRING
AS {
  RETURN prefix || name AS message
};

CREATE PROCEDURE knows_scores()
RETURNS (id INT64, score INT64)
AS {
  NODE VALUE score SumAgg<INT64> = 0
  TABLE result_rows TYPED TABLE {id INT64, score INT64} PARTITION BY DEFAULT

  MATCH (s:Person)-[:KNOWS]->(t:Person)
  PER PATH {
    SET t.@score += 1
  }

  MATCH (n:Person)
  PER NODE (n) {
    EXPORT n.id AS id, n.@score AS score INTO result_rows
  }

  PER PARTITION (part) OF result_rows {
    FOR row IN part
    RETURN row.id AS id, row.score AS score
  }
};

MATCH (p:Person {id: 1})-[:KNOWS]->(f:Person)
RETURN f.id AS id
LIMIT 10;

MATCH (p:Person)-[:KNOWS]->(f1:Person),
      (p)-[:KNOWS]->(f2:Person)
RETURN f1.id AS f1_id, f2.id AS f2_id;

MATCH (p:Person)
OPTIONAL MATCH (p)-[:KNOWS]->(f:Person WHERE f.age > 30)
RETURN p.id AS person_id, f.id AS friend_id;

MATCH (p:Person)
WHERE EXISTS {
  MATCH (p)-[:KNOWS]->(f:Person)
}
RETURN p.id AS id;
